  case unknown(String)

  /// The values the contract defines; never `unknown`.
  public static let allCases: [ContractErrorCode] = [
    .alreadyScheduled,
    .badGateway,
    .badRequest,
    .conflict,
    .forbidden,
    .internalServerError,
    .notFound,
    .positionMismatch,
    .tooManyRequests,
    .unauthorized,
  ]

  public init(rawValue: String) {
    switch rawValue {
    case "ALREADY_SCHEDULED": self = .alreadyScheduled
    case "BAD_GATEWAY": self = .badGateway
    case "BAD_REQUEST": self = .badRequest
    case "CONFLICT": self = .conflict
    case "FORBIDDEN": self = .forbidden
    case "INTERNAL_SERVER_ERROR": self = .internalServerError
    case "NOT_FOUND": self = .notFound
    case "POSITION_MISMATCH": self = .positionMismatch
    case "TOO_MANY_REQUESTS": self = .tooManyRequests
    case "UNAUTHORIZED": self = .unauthorized
    default: self = .unknown(rawValue)
    }
  }

  public var rawValue: String {
    switch self {
    case .alreadyScheduled: "ALREADY_SCHEDULED"
    case .badGateway: "BAD_GATEWAY"
    case .badRequest: "BAD_REQUEST"
    case .conflict: "CONFLICT"
    case .forbidden: "FORBIDDEN"
    case .internalServerError: "INTERNAL_SERVER_ERROR"
    case .notFound: "NOT_FOUND"
    case .positionMismatch: "POSITION_MISMATCH"
    case .tooManyRequests: "TOO_MANY_REQUESTS"
    case .unauthorized: "UNAUTHORIZED"
    case .unknown(let value): value
    }
  }

  public init(from decoder: any Decoder) throws {
    self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
  }

  public func encode(to encoder: any Encoder) throws {
    var container = encoder.singleValueContainer()
    try container.encode(rawValue)
  }

  public var codingKey: any CodingKey {
    ContractCodingKey(rawValue)
  }

  public init?<Key: CodingKey>(codingKey: Key) {
    self.init(rawValue: codingKey.stringValue)
  }
}
